import { FC, HTMLAttributes, useMemo } from 'react';
import { Link } from 'react-router-dom';

import { Flex, theme } from 'antd';

import ReportsLinkIcon from 'assets/images/icons/reportsLink.svg?react';
import {
	EReportGroupBy,
	EReportTypes,
	getDateFilters,
	IDateReport,
	IOfferReport,
	ISourceReport,
} from 'entities/Report';
import { EFilters } from 'features/Filters';
import { EMainRoutes } from 'shared/typings';
import { formatNumber } from 'shared/utils';

interface IReportActionsProps extends HTMLAttributes<HTMLDivElement> {
	report: IDateReport | IOfferReport | ISourceReport;
	date: Date | null;
	groupBy: EReportGroupBy;
	reportType: EReportTypes;
}

export const ReportActions: FC<IReportActionsProps> = ({ report, date, groupBy, reportType }) => {
	const dates = useMemo(() => getDateFilters(date), [date]);
	const {
		token: { colorTextQuaternary },
	} = theme.useToken();

	const link =
		reportType === EReportTypes.OFFER && 'offer' in report
			? `/${EMainRoutes.REPORTS}/?${EFilters.REPORT_TYPE}=${EReportTypes.ACTION}&${EFilters.OFFER_ID}=${report?.offer?.uuid}`
			: reportType === EReportTypes.DATE
				? `/${EMainRoutes.REPORTS}/?${EFilters.REPORT_TYPE}=${EReportTypes.ACTION}&${EFilters.DATE_AFTER}=${dates?.[groupBy]?.dateAfter}&${EFilters.DATE_BEFORE}=${dates?.[groupBy]?.dateBefore}`
				: reportType === EReportTypes.SOURCE && 'source' in report
					? `/${EMainRoutes.REPORTS}/?${EFilters.REPORT_TYPE}=${EReportTypes.ACTION}&${EFilters.SOURCE_ID}=${report?.source?.uuid}`
					: '';

	return (
		<Flex gap={8} align="center">
			{formatNumber(report.actions_count)}
			<Link to={link} style={{ lineHeight: 0, color: colorTextQuaternary }}>
				<ReportsLinkIcon style={{ width: 16, height: 16 }} />
			</Link>
		</Flex>
	);
};
