import { Typography } from 'antd';

import {
	EReportGroupBy,
	EReportTypes,
	IActionReport,
	IDateReport,
	IOfferReport,
	ISourceReport,
	ReportActions,
	ReportDate,
	ReportStatus,
} from 'entities/Report';
import { formatDate, formatNumber } from 'shared/utils';
import { ReportCell, ReportConversionType, ReportOffer, ReportSource } from 'widgets/ReportsList';

const { Text } = Typography;

export const getReport = (
	report: IDateReport | IActionReport | IOfferReport | ISourceReport,
	key: number,
	groupBy: EReportGroupBy,
	reportType: EReportTypes,
) => {
	if (report.is_total) {
		return {
			key,
			date: <Text strong>{'date' in report && report.date}</Text>,
			order_id: <Text strong>{'order_id' in report && report.order_id}</Text>,
			date_time: <Text strong>-</Text>,
			offer: <Text strong>{'offer' in report && (report.offer as unknown as string)}</Text>,
			brand: <Text strong>-</Text>,
			source: <Text strong>{'source' in report && (report.source as unknown as string)}</Text>,
			clicks_count: <Text strong>{'clicks_count' in report ? formatNumber(report.clicks_count) || '-' : '-'}</Text>,
			cross_sell_count: (
				<Text strong>{'cross_sell_count' in report ? formatNumber(report.cross_sell_count) || '-' : '-'}</Text>
			),
			direct_sell_count: (
				<Text strong>{'direct_sell_count' in report ? formatNumber(report.direct_sell_count) || '-' : '-'}</Text>
			),
			cross_sell: <Text strong>-</Text>,
			click_offer: <Text strong>-</Text>,
			actions_count: <Text strong>{'actions_count' in report ? formatNumber(report.actions_count) || '-' : '-'}</Text>,
			cr: <Text strong>{'cr' in report ? formatNumber(report.cr) : '-'}</Text>,
			ar: <Text strong>{'ar' in report ? formatNumber(report.ar) : '-'}</Text>,
			epc: <Text strong>{'epc' in report ? formatNumber(report.epc) : '-'}</Text>,
			epl: <Text strong>{'epl' in report ? formatNumber(report.epl) : '-'}</Text>,
			geo: <Text strong>-</Text>,
			title: <Text strong>-</Text>,
			status: <Text strong>-</Text>,
			pending_amount: <Text strong>{'pending_amount' in report ? formatNumber(report.pending_amount) : '-'}</Text>,
			rejected_amount: <Text strong>{'rejected_amount' in report ? formatNumber(report.rejected_amount) : '-'}</Text>,
			approved_amount: <Text strong>{'approved_amount' in report ? formatNumber(report.approved_amount) : '-'}</Text>,
			amount: <Text strong>{'amount' in report ? formatNumber(report.amount) : '-'}</Text>,
			subid1: <Text strong>-</Text>,
			subid2: <Text strong>-</Text>,
			subid3: <Text strong>-</Text>,
			ip_addr: <Text strong>-</Text>,
		};
	}

	const date = 'date' in report ? new Date(report.date) : null;

	return {
		key,
		date: <ReportDate groupBy={groupBy} date={date} />,
		order_id: <Text>{'order_id' in report ? report.order_id || '-' : '-'}</Text>,
		date_time: <Text>{'date' in report ? formatDate(new Date(report.date), 'full') || '-' : '-'}</Text>,
		offer: 'offer' in report ? <ReportOffer offer={report.offer} reportType={reportType} /> : '-',
		cross_sell: 'cross_sell' in report ? <ReportConversionType isCrossSell={report.cross_sell} /> : '-',
		click_offer: 'click_offer' in report ? <ReportOffer offer={report.click_offer} reportType={reportType} /> : '-',
		brand: <Text>{'brand' in report ? <ReportCell label={report?.brand?.name || '-'} /> : '-'}</Text>,
		source: 'source' in report ? <ReportSource source={report.source} reportType={reportType} /> : '-',
		clicks_count: <Text>{'clicks_count' in report ? formatNumber(report.clicks_count) || '-' : '-'}</Text>,
		cross_sell_count: <Text>{'cross_sell_count' in report ? formatNumber(report.cross_sell_count) || '-' : '-'}</Text>,
		direct_sell_count: (
			<Text>{'direct_sell_count' in report ? formatNumber(report.direct_sell_count) || '-' : '-'}</Text>
		),
		actions_count: (
			<Text>
				{'actions_count' in report ? (
					<ReportActions report={report} groupBy={groupBy} date={date} reportType={reportType} />
				) : (
					'-'
				)}
			</Text>
		),
		cr: <Text>{'cr' in report ? formatNumber(report.cr) || '-' : '-'}</Text>,
		ar: <Text>{'ar' in report ? formatNumber(report.ar) || '-' : '-'}</Text>,
		epc: <Text>{'epc' in report ? formatNumber(report.epc) || '-' : '-'}</Text>,
		epl: <Text>{'epl' in report ? formatNumber(report.epl) || '-' : '-'}</Text>,
		geo: <Text>{'geo' in report ? report.geo || '-' : '-'}</Text>,
		title: <Text>{'title' in report ? report.title || '-' : '-'}</Text>,
		status: 'status' in report ? <ReportStatus status={report.status} comment={report.comment} /> : '-',
		pending_amount: <Text>{'pending_amount' in report ? formatNumber(report.pending_amount) : '-'}</Text>,
		rejected_amount: <Text>{'rejected_amount' in report ? formatNumber(report.rejected_amount) : '-'}</Text>,
		approved_amount: <Text>{'approved_amount' in report ? formatNumber(report.approved_amount) : '-'}</Text>,
		amount: <Text>{'amount' in report ? formatNumber(report.amount) : '-'}</Text>,
		subid1: <Text>{'subid1' in report ? report.subid1 || '-' : '-'}</Text>,
		subid2: <Text>{'subid2' in report ? report.subid2 || '-' : '-'}</Text>,
		subid3: <Text>{'subid3' in report ? report.subid3 || '-' : '-'}</Text>,
		ip_addr: <Text>{'ip_addr' in report ? report.ip_addr || '-' : '-'}</Text>,
	};
};
