import { Dispatch, FC, HTMLAttributes, SetStateAction } from 'react';

import {
	closestCenter,
	DndContext,
	DragEndEvent,
	KeyboardSensor,
	PointerSensor,
	useSensor,
	useSensors,
} from '@dnd-kit/core';
import {
	arrayMove,
	SortableContext,
	sortableKeyboardCoordinates,
	verticalListSortingStrategy,
} from '@dnd-kit/sortable';

import { EReportTypes } from 'entities/Report';
import { EFilters, useFilters } from 'features/Filters';
import { COLS_STORAGE_FIELD, ICol } from 'widgets/ReportsList';

import { ReportsSotrItem } from '../ReportsSotrItem/ReportsSotrItem';

interface IReportsSortProps extends HTMLAttributes<HTMLDivElement> {
	columns: ICol[];
	setColumns: Dispatch<SetStateAction<ICol[]>>;
}

export const ReportsSort: FC<IReportsSortProps> = ({ setColumns, columns }) => {
	const { getFilterValue } = useFilters();

	const sensors = useSensors(
		useSensor(PointerSensor),
		useSensor(KeyboardSensor, {
			coordinateGetter: sortableKeyboardCoordinates,
		}),
	);

	const onDragEnd = (event: DragEndEvent) => {
		const { active, over } = event;

		if (active.id !== over?.id) {
			setColumns((columns) => {
				const oldIndex = columns.findIndex((column) => column.id === active.id);
				const newIndex = columns.findIndex((column) => column.id === over?.id);

				const newColumns = arrayMove(columns, oldIndex, newIndex);
				localStorage.setItem(COLS_STORAGE_FIELD, JSON.stringify(newColumns));
				return newColumns;
			});
		}
	};

	const onChange = (checked: boolean, id: string) => {
		const newColumns = columns.map((column) => (column.id === id ? { ...column, visible: checked } : column));
		setColumns(newColumns);
		localStorage.setItem(COLS_STORAGE_FIELD, JSON.stringify(newColumns));
	};

	return (
		<DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={onDragEnd}>
			<SortableContext items={columns} strategy={verticalListSortingStrategy}>
				{columns?.map(
					(column) =>
						column.groups.includes((getFilterValue(EFilters.REPORT_TYPE) as EReportTypes) || EReportTypes.DATE) && (
							<ReportsSotrItem key={column.id} item={column} onVisibleChange={onChange} />
						),
				)}
			</SortableContext>
		</DndContext>
	);
};
