import { FC, HTMLAttributes, ReactNode } from 'react';

import { Flex, Typography } from 'antd';

const { Text } = Typography;

interface IReportCellProps extends HTMLAttributes<HTMLDivElement> {
	label: ReactNode;
	value?: ReactNode;
}

export const ReportCell: FC<IReportCellProps> = ({ className, label, value, ...props }) => {
	return (
		<Flex vertical {...props} className={className}>
			<Text ellipsis={{ tooltip: label }} style={{ maxWidth: 200 }}>
				{label}
			</Text>
			{value && (
				<Text ellipsis={{ tooltip: { title: value } }} type="secondary" style={{ maxWidth: 300, fontSize: 12 }}>
					{value}
				</Text>
			)}
		</Flex>
	);
};
