import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, theme } from 'antd';

import CrossConversionIcon from 'assets/images/icons/reports/cross-conversion.svg?react';
import DirectConversionIcon from 'assets/images/icons/reports/direct-conversion.svg?react';
interface IReportConversionTypeProps extends HTMLAttributes<HTMLDivElement> {
	isCrossSell: boolean;
}

export const ReportConversionType: FC<IReportConversionTypeProps> = ({ isCrossSell }) => {
	const { t } = useTranslation();

	const {
		token: { colorPrimary, purple4 },
	} = theme.useToken();

	const type = {
		label: isCrossSell ? t('Кросс') : t('Прямая'),
		color: isCrossSell ? purple4 : colorPrimary,
		icon: isCrossSell ? <CrossConversionIcon /> : <DirectConversionIcon />,
	};

	return (
		<Flex gap={4} align="center" style={{ color: type.color, fontSize: 12 }}>
			{type.icon}
			{type.label}
		</Flex>
	);
};
