import { HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Badge, Button, DatePicker, Flex, Select } from 'antd';
import cn from 'classnames';

import FiltersIcon from 'assets/images/icons/filters.svg?react';
import { EReportGroupBy, EReportTypes } from 'entities/Report';
import { EFilters, ReportsExtendedFilters, useDateFilters, useFilters } from 'features/Filters';
import { useTrans } from 'shared/hooks';

import styles from './ReportsFilters.module.scss';

export interface IReportsFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const ReportsFilters = ({ className, ...props }: IReportsFiltersProps) => {
	const { t } = useTranslation();
	const { reportTypes } = useTrans();
	const [filtersIsOpened, setFiltersIsOpened] = useState(false);
	const { getFiltersCount, onFilterChange, getFilterValue, clearFilters } = useFilters();
	const { dateAfter, dateBefore, onDateChange } = useDateFilters(EFilters.DATE_AFTER, EFilters.DATE_BEFORE);

	return (
		<Flex vertical gap={16}>
			<div {...props} className={cn(className, styles.filters)}>
				<DatePicker.RangePicker
					size="small"
					format="DD.MM.YYYY"
					placeholder={[t('Дата с'), t('Дата по')]}
					value={[dateAfter, dateBefore]}
					onChange={(value) => {
						onDateChange(value?.[0] || null, EFilters.DATE_AFTER, true, false);
						onDateChange(value?.[1] || null, EFilters.DATE_BEFORE, true, true);
					}}
				/>

				<Select
					size="small"
					onChange={(value) => {
						clearFilters([
							EFilters.REPORT_GROUP_BY,
							EFilters.STATUS,
							EFilters.COUNTRY_ID,
							EFilters.SEARCH_ID,
							EFilters.SUBID1,
							EFilters.SUBID2,
							EFilters.SUBID3,
						]);
						onFilterChange(EFilters.REPORT_TYPE, value);
					}}
					defaultValue={EReportTypes.DATE}
					value={getFilterValue(EFilters.REPORT_TYPE) || EReportTypes.DATE}
					options={Object.entries(reportTypes).map(([value, label]) => ({ label, value }))}
					showSearch
					optionFilterProp="label"
					placeholder={t('Выбрать группировку')}
					allowClear
				/>

				<Button size="small" icon={<FiltersIcon />} onClick={() => setFiltersIsOpened(true)}>
					{t('Фильтры')}{' '}
					<Badge
						size="small"
						count={getFiltersCount([
							EFilters.DATE_AFTER,
							EFilters.DATE_BEFORE,
							EFilters.SOURCE_ID,
							EFilters.BRAND_ID,
							EFilters.OFFER_ID,
							EFilters.STATUS,
							EFilters.COUNTRY_ID,
							EFilters.SEARCH_ID,
						])}
					/>
				</Button>

				<ReportsExtendedFilters open={filtersIsOpened} onClose={() => setFiltersIsOpened(false)} />
			</div>

			{(!getFilterValue(EFilters.REPORT_TYPE) || getFilterValue(EFilters.REPORT_TYPE) === EReportTypes.DATE) && (
				<Flex gap={12}>
					<Button
						size="small"
						onClick={() => onFilterChange(EFilters.REPORT_GROUP_BY, EReportGroupBy.DAY)}
						variant="outlined"
						color={
							!getFilterValue(EFilters.REPORT_GROUP_BY) ||
							getFilterValue(EFilters.REPORT_GROUP_BY) === EReportGroupBy.DAY
								? 'primary'
								: 'default'
						}>
						{t('По дням')}
					</Button>

					<Button
						size="small"
						onClick={() => onFilterChange(EFilters.REPORT_GROUP_BY, EReportGroupBy.MONTH)}
						variant="outlined"
						color={getFilterValue(EFilters.REPORT_GROUP_BY) === EReportGroupBy.MONTH ? 'primary' : 'default'}>
						{t('По месяцам')}
					</Button>

					<Button
						size="small"
						onClick={() => onFilterChange(EFilters.REPORT_GROUP_BY, EReportGroupBy.YEAR)}
						variant="outlined"
						color={getFilterValue(EFilters.REPORT_GROUP_BY) === EReportGroupBy.YEAR ? 'primary' : 'default'}>
						{t('По годам')}
					</Button>
				</Flex>
			)}
		</Flex>
	);
};

export default ReportsFilters;
