import { FC, HTMLAttributes, useMemo } from 'react';
import { Link } from 'react-router-dom';

import { EReportGroupBy, EReportTypes, getDateFilters } from 'entities/Report';
import { EFilters } from 'features/Filters';
import { EMainRoutes } from 'shared/typings';

interface IReportDateProps extends HTMLAttributes<HTMLDivElement> {
	date: Date | null;
	groupBy: EReportGroupBy;
}

export const ReportDate: FC<IReportDateProps> = ({ date, groupBy }) => {
	const dates = useMemo(() => getDateFilters(date), [date]);

	return (
		<Link
			to={`/${EMainRoutes.REPORTS}/?${EFilters.REPORT_TYPE}=${EReportTypes.ACTION}&${EFilters.DATE_AFTER}=${dates?.[groupBy]?.dateAfter}&${EFilters.DATE_BEFORE}=${dates?.[groupBy]?.dateBefore}`}>
			{dates?.[groupBy]?.date || '-'}
		</Link>
	);
};
