import { HTMLAttributes } from 'react';

import { Badge, Flex, Typography } from 'antd';

import { EActionReportStatuses } from 'entities/Report';
import { useTrans } from 'shared/hooks';
import { InfoTooltip } from 'shared/ui';

interface IReportStatusProps extends HTMLAttributes<HTMLDivElement> {
	status: EActionReportStatuses;
	comment?: string;
}

export const ReportStatus = ({ status, comment, ...props }: IReportStatusProps) => {
	const { reportStatuses } = useTrans();

	return (
		<Flex align="center" gap={8}>
			<Badge
				{...props}
				status={reportStatuses[status]?.status}
				text={
					<Typography.Text ellipsis={{ tooltip: reportStatuses[status]?.name }} style={{ maxWidth: 200 }}>
						{reportStatuses[status]?.name}
					</Typography.Text>
				}
			/>

			{status === EActionReportStatuses.REJECTED && !!comment && <InfoTooltip text={comment} />}
		</Flex>
	);
};
