import { FC, useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Checkbox, Drawer, DrawerProps, Flex, Form, Input, Select } from 'antd';
import cn from 'classnames';

import { EReportTypes } from 'entities/Report';
import { EFilters, useFilters } from 'features/Filters';
import { useCommonSlice, useDisableBodyScroll, useMeta, useTrans } from 'shared/hooks';
import { InfoTooltip } from 'shared/ui';

import styles from './ReportsExtendedFilters.module.scss';

interface IReportsExtendedFiltersProps extends DrawerProps {}

export const ReportsExtendedFilters: FC<IReportsExtendedFiltersProps> = ({ className, onClose, open, ...props }) => {
	const { t } = useTranslation();
	const {
		sourcesOptions,
		brandsOptions,
		offersOptions,
		platformTypesMap,
		sourcesIsFetching,
		brandsIsFetching,
		offersIsFetching,
		onFilterChange,
		getFilterValue,
		getALLFilterValues,
		clearFilters,
	} = useFilters();
	const { offersMap } = useMeta();
	const { reportStatusOptions, reportConvertionsOptions } = useTrans();
	const { countryOptions } = useCommonSlice();

	const [search, setSearch] = useState(getFilterValue(EFilters.SEARCH_ID) || '');
	const [subId1, setSubId1] = useState(getFilterValue(EFilters.SUBID1) || '');
	const [subId2, setSubId2] = useState(getFilterValue(EFilters.SUBID2) || '');
	const [subId3, setSubId3] = useState(getFilterValue(EFilters.SUBID3) || '');

	const platforms = platformTypesMap?.[getALLFilterValues(EFilters.SOURCE_ID)[0]];

	const currentOffers = getALLFilterValues(EFilters.OFFER_ID);

	const landings = useMemo(
		() =>
			currentOffers.flatMap((offerId) =>
				(offersMap?.[offerId]?.landings || [])?.map(({ code, name }) => ({ value: code, label: name })),
			),
		[currentOffers.length], //eslint-disable-line
	);

	useEffect(() => {
		onFilterChange(
			EFilters.LANDING_CODE,
			getALLFilterValues(EFilters.LANDING_CODE).filter((code) => landings.find(({ value }) => value === code)),
		);
	}, [landings]); //eslint-disable-line

	useDisableBodyScroll(!!open);

	return (
		<Drawer
			{...props}
			open={open}
			onClose={onClose}
			width={450}
			title={t('Фильтры')}
			className={cn(className, styles.brandExtendedFilters)}>
			<Flex vertical gap={16}>
				<Form.Item label={t('Площадка')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.SOURCE_ID, value)}
						value={sourcesIsFetching ? null : getALLFilterValues(EFilters.SOURCE_ID)}
						options={sourcesOptions}
						loading={sourcesIsFetching}
						disabled={sourcesIsFetching}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать площадку')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				{getALLFilterValues(EFilters.SOURCE_ID).length === 1 && !!platforms?.length && platforms.length > 1 && (
					<Form.Item label={t('Платформа')} layout="vertical">
						<Select
							mode="multiple"
							maxTagCount="responsive"
							onChange={(value) => onFilterChange(EFilters.PLATFORM_CODE, value)}
							value={getALLFilterValues(EFilters.PLATFORM_CODE)}
							options={platforms.map((platform) => ({ value: platform?.code, label: platform.url }))}
							showSearch
							optionFilterProp="label"
							placeholder={t('Выбрать платформу')}
							allowClear
							getPopupContainer={(trigger) => trigger.parentElement}
						/>
					</Form.Item>
				)}

				<Form.Item label={t('Рекламодатель')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.BRAND_ID, value)}
						value={brandsIsFetching ? null : getALLFilterValues(EFilters.BRAND_ID)}
						options={brandsOptions}
						loading={brandsIsFetching}
						disabled={brandsIsFetching}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать рекламодателя')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Оффер')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.OFFER_ID, value)}
						value={offersIsFetching ? null : getALLFilterValues(EFilters.OFFER_ID)}
						options={offersOptions}
						loading={offersIsFetching}
						disabled={offersIsFetching}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать оффер')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				{landings.length > 0 && (
					<Form.Item label={t('Лендинг')} layout="vertical">
						<Select
							mode="multiple"
							maxTagCount="responsive"
							onChange={(value) => onFilterChange(EFilters.LANDING_CODE, value)}
							value={getALLFilterValues(EFilters.LANDING_CODE)}
							options={landings}
							showSearch
							optionFilterProp="label"
							placeholder={t('Выбрать лендинг')}
							allowClear
							getPopupContainer={(trigger) => trigger.parentElement}
						/>
					</Form.Item>
				)}

				{getFilterValue(EFilters.REPORT_TYPE) === EReportTypes.ACTION && (
					<>
						<Form.Item label={t('Показать типы конверсий')} layout="vertical">
							<Select
								mode="multiple"
								maxTagCount="responsive"
								onChange={(value) => onFilterChange(EFilters.CROSS_SELL, value)}
								value={getALLFilterValues(EFilters.CROSS_SELL)}
								options={reportConvertionsOptions}
								showSearch
								optionFilterProp="label"
								placeholder={t('Выбрать типы конверсий')}
								allowClear
								getPopupContainer={(trigger) => trigger.parentElement}
							/>
						</Form.Item>

						<Form.Item label={t('Статус')} layout="vertical">
							<Select
								mode="multiple"
								maxTagCount="responsive"
								onChange={(value) => onFilterChange(EFilters.STATUS, value)}
								value={getALLFilterValues(EFilters.STATUS)}
								options={reportStatusOptions}
								showSearch
								optionFilterProp="label"
								placeholder={t('Выбрать статус')}
								allowClear
								getPopupContainer={(trigger) => trigger.parentElement}
							/>
						</Form.Item>

						<Form.Item label={t('Гео')} layout="vertical">
							<Select
								mode="multiple"
								maxTagCount="responsive"
								onChange={(value) => onFilterChange(EFilters.COUNTRY_ID, value)}
								value={getALLFilterValues(EFilters.COUNTRY_ID)}
								options={countryOptions}
								showSearch
								optionFilterProp="label"
								placeholder={t('Выбрать страну')}
								allowClear
								getPopupContainer={(trigger) => trigger.parentElement}
							/>
						</Form.Item>

						<Form.Item label={t('Поиск по ID заявки')} layout="vertical">
							<Input
								placeholder="Укажите ID заявки"
								onChange={(value) => setSearch(value.target.value)}
								value={search}
								onPressEnter={() => onFilterChange(EFilters.SEARCH_ID, search)}
								onClear={() => onFilterChange(EFilters.SEARCH_ID, '')}
								allowClear
							/>
						</Form.Item>

						<Form.Item label={t('Поиск по SubID')} layout="vertical">
							<Flex vertical gap={12}>
								<Input
									placeholder="Укажите SubID 1"
									onChange={(value) => setSubId1(value.target.value)}
									value={subId1}
									onPressEnter={() => onFilterChange(EFilters.SUBID1, subId1)}
									onClear={() => onFilterChange(EFilters.SUBID1, '')}
									allowClear
								/>
								<Input
									placeholder="Укажите SubID 2"
									onChange={(value) => setSubId2(value.target.value)}
									value={subId2}
									onPressEnter={() => onFilterChange(EFilters.SUBID2, subId2)}
									onClear={() => onFilterChange(EFilters.SUBID2, '')}
									allowClear
								/>
								<Input
									placeholder="Укажите SubID 3"
									onChange={(value) => setSubId3(value.target.value)}
									value={subId3}
									onPressEnter={() => onFilterChange(EFilters.SUBID3, subId3)}
									onClear={() => onFilterChange(EFilters.SUBID3, '')}
									allowClear
								/>
							</Flex>
						</Form.Item>
					</>
				)}

				{getFilterValue(EFilters.REPORT_TYPE) !== EReportTypes.ACTION && (
					<Flex vertical gap={8}>
						<Checkbox
							onChange={(e) => {
								onFilterChange(EFilters.ONLY_DIRECT_SELL, undefined);
								onFilterChange(EFilters.ONLY_CROSS_SELL, e.target.checked ? 'true' : undefined);
							}}
							checked={getFilterValue(EFilters.ONLY_CROSS_SELL) === 'true'}>
							{t('Только Кросс-заявки')}{' '}
							<InfoTooltip
								text={t('Оплата всех целевых действий в рамках одного бренда без привязки к ссылке перехода (оффера).')}
							/>
						</Checkbox>
						<Checkbox
							onChange={(e) => {
								onFilterChange(EFilters.ONLY_CROSS_SELL, undefined);
								onFilterChange(EFilters.ONLY_DIRECT_SELL, e.target.checked ? 'true' : undefined);
							}}
							checked={getFilterValue(EFilters.ONLY_DIRECT_SELL) === 'true'}>
							{t('Только Прямые заявки')}
						</Checkbox>
					</Flex>
				)}

				<Flex justify="space-between" className={styles.buttons}>
					<Button
						onClick={(e) => {
							clearFilters();
							onClose?.(e);
						}}>
						{t('Сбросить фильтры')}
					</Button>
					<Button
						type="primary"
						onClick={(e) => {
							onFilterChange(EFilters.SEARCH_ID, search);
							onFilterChange(EFilters.SUBID1, subId1);
							onFilterChange(EFilters.SUBID2, subId2);
							onFilterChange(EFilters.SUBID3, subId3);
							onClose?.(e);
						}}>
						{t('Применить')}
					</Button>
				</Flex>
			</Flex>
		</Drawer>
	);
};
