import { FC, HTMLAttributes } from 'react';
import { Link } from 'react-router-dom';

import { EReportTypes } from 'entities/Report';
import { EFilters } from 'features/Filters';
import { EMainRoutes } from 'shared/typings';

interface IReportSourceProps extends HTMLAttributes<HTMLDivElement> {
	source: { uuid: string; name: string } | null;
	reportType: EReportTypes;
}

export const ReportSource: FC<IReportSourceProps> = ({ source, reportType }) => {
	const link =
		reportType === EReportTypes.SOURCE
			? `/${EMainRoutes.REPORTS}/?${EFilters.REPORT_TYPE}=${EReportTypes.ACTION}&${EFilters.SOURCE_ID}=${source?.uuid}`
			: `/${EMainRoutes.REPORTS}/?${EFilters.REPORT_TYPE}=${EReportTypes.SOURCE}&${EFilters.SOURCE_ID}=${source?.uuid}`;

	return source?.uuid ? <Link to={link}>{source?.name || '-'}</Link> : source?.name || '-';
};
