import { FC, HTMLAttributes } from 'react';

import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

import { Checkbox, Flex } from 'antd';

import DragIcon from 'assets/images/icons/drag.svg?react';
import { ICol } from 'widgets/ReportsList';

interface IReportsSotrItemProps extends HTMLAttributes<HTMLDivElement> {
	item: { id: string } & ICol;
	onVisibleChange: (checked: boolean, id: string) => void;
}

export const ReportsSotrItem: FC<IReportsSotrItemProps> = ({ item, onVisibleChange }) => {
	const { attributes, listeners, setNodeRef, setActivatorNodeRef, transform, transition } = useSortable({
		id: item.id,
	});

	const style = {
		transform: CSS.Transform.toString(transform),
		transition,
		padding: '5px 12px',
	};

	return (
		<Flex ref={setNodeRef} style={style} gap={12}>
			<div ref={setActivatorNodeRef} {...attributes} {...listeners} style={{ cursor: 'grab', touchAction: 'none' }}>
				<DragIcon />
			</div>
			<Checkbox checked={item.visible} onChange={(e) => onVisibleChange(e.target.checked, item.id)}>
				{item.title}
			</Checkbox>
		</Flex>
	);
};
