import { EReportGroupBy } from 'entities/Report/';
import { formatDate } from 'shared/utils';

export const getDateFilters = (date: Date | null) => {
	return {
		[EReportGroupBy.DAY]: {
			date: formatDate(date, 'short'),
			dateAfter: `${formatDate(date, 'iso')}T00%3A00%3A00.000`,
			dateBefore: `${formatDate(date, 'iso')}T23%3A59%3A59.999`,
		},
		[EReportGroupBy.MONTH]: {
			date: formatDate(date, 'month'),
			dateAfter: date
				? `${date.getFullYear()}-${date.toLocaleString('sv-SE', { month: '2-digit' })}-01T00%3A00%3A00.000`
				: '',
			dateBefore: date
				? `${date.getFullYear()}-${date.toLocaleString('sv-SE', { month: '2-digit' })}-${new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate()}T23%3A59%3A59.999`
				: '',
		},
		[EReportGroupBy.YEAR]: {
			date: formatDate(date, 'year'),
			dateAfter: date ? `${date.getFullYear()}-01-01T00%3A00%3A00.000` : '',
			dateBefore: date ? `${date.getFullYear()}-12-31T23%3A59%3A59.999` : '',
		},
	};
};
