import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, Typography } from 'antd';

import { ReportChart, useGetReportsChartQuery, useReportsSlice } from 'entities/Report';
import { EFilters, ReportsPeriodFilters } from 'features/Filters';
import { OverlayLoader } from 'shared/ui';

interface IStatsChartProps extends HTMLAttributes<HTMLDivElement> {}

export const StatsChart: FC<IStatsChartProps> = ({ ...props }) => {
	const { t } = useTranslation();

	const { chartFilters } = useReportsSlice();
	const searchParams = new URLSearchParams(
		Object.keys(chartFilters).reduce((acc, key) => {
			return chartFilters[key as EFilters] ? { ...acc, [key]: chartFilters[key as EFilters] } : acc;
		}, {}),
	);

	const { data, isFetching } = useGetReportsChartQuery(searchParams.toString());

	return (
		<Flex {...props} vertical gap={16} style={{ position: 'relative' }}>
			{isFetching && <OverlayLoader />}

			<Typography.Title level={5} style={{ margin: 0 }}>
				{t('Статистика по заработку')}
			</Typography.Title>

			<ReportsPeriodFilters />

			<ReportChart data={data} isFetching={isFetching} />
		</Flex>
	);
};
