import { HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, DatePicker, Select } from 'antd';

import { useReportsSlice } from 'entities/Report';
import { EFilters, prepareDate, useDateFilters } from 'features/Filters';
import { useMedia } from 'shared/hooks';
import { formatDate, getDateDiff } from 'shared/utils';

import styles from './ReportsPeriodFilters.module.scss';

export interface IReportsPeriodFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const ReportsPeriodFilters = ({ ...props }: IReportsPeriodFiltersProps) => {
	const { t } = useTranslation();
	const isMd = useMedia();
	const { chartFilters, setFilter } = useReportsSlice();

	const dateFromKey = EFilters.DATE_AFTER;
	const dateToKey = EFilters.DATE_BEFORE;

	const { dateAfter, dateBefore, onDateChange } = useDateFilters(dateFromKey, dateToKey, true);

	const setPeriod = (diff: number | null = 0) => {
		if (diff === null) {
			setFilter({ name: dateFromKey, value: null });
			setFilter({ name: dateToKey, value: null });
			return;
		}

		const endDate = prepareDate(new Date());
		const startDate = prepareDate(new Date(), diff);

		setFilter({ name: dateFromKey, value: formatDate(startDate, 'iso') || null });
		setFilter({ name: dateToKey, value: formatDate(endDate, 'iso') || null });
	};

	const periodIsActive = (diff: number = 0) =>
		chartFilters[dateFromKey] === formatDate(prepareDate(new Date(), diff), 'iso') &&
		chartFilters[dateToKey] === formatDate(prepareDate(new Date()), 'iso');

	const dateDiff = getDateDiff(new Date(chartFilters[dateFromKey] || ''), new Date(chartFilters[dateToKey] || ''));

	return (
		<div {...props} className={styles.filters}>
			{!isMd && (
				<>
					<Button
						size="small"
						variant="outlined"
						color={periodIsActive(6) ? 'primary' : 'default'}
						onClick={() => setPeriod(6)}>
						{t('За последние 7 дней')}
					</Button>
					<Button
						size="small"
						variant="outlined"
						color={periodIsActive(29) ? 'primary' : 'default'}
						onClick={() => setPeriod(29)}>
						{t('За последние 30 дней')}
					</Button>
					<Button
						size="small"
						variant="outlined"
						color={periodIsActive(89) ? 'primary' : 'default'}
						onClick={() => setPeriod(89)}>
						{t('За последние 90 дней')}
					</Button>
					<Button
						size="small"
						variant="outlined"
						color={periodIsActive(364) ? 'primary' : 'default'}
						onClick={() => setPeriod(364)}>
						{t('Последний год')}
					</Button>
				</>
			)}

			{isMd && (
				<Select
					size="small"
					onChange={(value) => setPeriod(value !== undefined ? Number(value) : null)}
					value={[6, 29, 89, 364].includes(dateDiff) ? dateDiff : null}
					options={[
						{
							value: 6,
							label: t('За последние 7 дней'),
						},
						{
							value: 29,
							label: t('За последние 30 дней'),
						},
						{
							value: 89,
							label: t('За последние 90 дней'),
						},
						{
							value: 364,
							label: t('Последний год'),
						},
					]}
					showSearch
					optionFilterProp="label"
					placeholder={t('Выбрать период')}
					allowClear
				/>
			)}

			<DatePicker.RangePicker
				size="small"
				format="DD.MM.YYYY"
				placeholder={[t('Дата с'), t('Дата по')]}
				value={[dateAfter, dateBefore]}
				style={{ minWidth: 230 }}
				onChange={(value) => {
					onDateChange(value?.[0] || null, dateFromKey);
					onDateChange(value?.[1] || null, dateToKey);
				}}
			/>
		</div>
	);
};

export default ReportsPeriodFilters;
