import { FC, HTMLAttributes } from 'react';
import { Link } from 'react-router-dom';

import { IOffer } from 'entities/Offer';
import { EReportTypes } from 'entities/Report';
import { EFilters } from 'features/Filters';
import { useTrans } from 'shared/hooks';
import { EMainRoutes } from 'shared/typings';
import { ReportCell } from 'widgets/ReportsList';

interface IReportOfferProps extends HTMLAttributes<HTMLDivElement> {
	offer: IOffer | null;
	reportType: EReportTypes;
}

export const ReportOffer: FC<IReportOfferProps> = ({ offer, reportType }) => {
	const { categories } = useTrans();
	const link =
		reportType === EReportTypes.OFFER
			? `/${EMainRoutes.REPORTS}/?${EFilters.REPORT_TYPE}=${EReportTypes.ACTION}&${EFilters.OFFER_ID}=${offer?.uuid}`
			: `/${EMainRoutes.REPORTS}/?${EFilters.REPORT_TYPE}=${EReportTypes.OFFER}&${EFilters.OFFER_ID}=${offer?.uuid}`;

	return (
		<ReportCell
			label={
				offer?.uuid && reportType !== EReportTypes.ACTION ? <Link to={link}>{offer?.name}</Link> : offer?.name || '-'
			}
			value={offer?.categories?.map(({ slug }) => categories[slug]).join(', ') || ''}
		/>
	);
};
