import { FC, HTMLAttributes, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { Button, ConfigProvider, Flex, Popover, Table, TableColumnsType, Typography } from 'antd';

import ExportIcon from 'assets/images/icons/export.svg?react';
import TableIcon from 'assets/images/icons/table.svg?react';
import {
	EReportGroupBy,
	EReportTypes,
	getReport,
	IActionReport,
	useExportReportMutation,
	useGetReportsListQuery,
} from 'entities/Report';
import { EFilters, ReportsFilters, useFilters } from 'features/Filters';
import { Pagination } from 'features/Pagination';
import { useGetAppConfigQuery } from 'shared/api/commonApi';
import { useCommonSlice, useMedia } from 'shared/hooks';
import { EmptyState, OverlayLoader } from 'shared/ui';
import { getDefaultSortOrder, getTableSorter } from 'shared/utils';
import { getColumns, IReportDataType, ReportsSort } from 'widgets/ReportsList';

import styles from './ReportsList.module.scss';

interface IReportsListProps extends HTMLAttributes<HTMLDivElement> {}

export const ReportsList: FC<IReportsListProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const isMd = useMedia();
	const { data: appConfig } = useGetAppConfigQuery();
	const { currenciesMap } = useCommonSlice();
	const [searchParams, setSearchParams] = useSearchParams();
	const { getFilterValue } = useFilters();
	const reportType = (getFilterValue(EFilters.REPORT_TYPE) as EReportTypes) || EReportTypes.DATE;
	const reportGroubBy = (getFilterValue(EFilters.REPORT_GROUP_BY) as EReportGroupBy) || EReportGroupBy.DAY;
	const { data, isFetching } = useGetReportsListQuery({
		type: reportType,
		groupBy: reportGroubBy,
		params: searchParams.toString(),
	});
	const hasData = !!data?.results?.length;

	const [exportReport] = useExportReportMutation();

	const currency = appConfig?.user?.balance?.currency || '';
	const [columns, setColumns] = useState(getColumns(currenciesMap[currency] || currency));

	useEffect(() => {
		setColumns(getColumns(currenciesMap[currency] || currency));
	}, [appConfig?.user?.balance?.currency]); //eslint-disable-line

	const tableProps = {
		bordered: false,
		scroll: { x: 'max-content' },
		pagination: false as const,
		showSorterTooltip: false,
		columns: columns
			.filter(({ visible, groups }) => visible && groups.includes(reportType))
			.map((col) => ({
				...col,
				dataIndex: col.sortField || col.id,
				key: col.id,
				defaultSortOrder: col.sorter && getDefaultSortOrder(col.sortField || col.id),
			})) as TableColumnsType<IReportDataType>,
	};

	const results = data?.results?.length
		? [
				...data.results,
				{
					...data.total_current_page,
					is_total: true,
					date: reportType === EReportTypes.DATE ? t('Всего на странице:') : undefined,
					offer: reportType === EReportTypes.OFFER ? t('Всего на странице:') : '-',
					source: reportType === EReportTypes.SOURCE ? t('Всего на странице:') : '-',
					order_id: reportType === EReportTypes.ACTION ? t('Всего на странице:') : undefined,
				},
				{
					...data.total_all_pages,
					is_total: true,
					date: reportType === EReportTypes.DATE ? t('Всего:') : undefined,
					offer: reportType === EReportTypes.OFFER ? t('Всего:') : '-',
					source: reportType === EReportTypes.SOURCE ? t('Всего:') : '-',
					order_id: reportType === EReportTypes.ACTION ? t('Всего:') : undefined,
				},
			]
		: [];

	return (
		<Flex {...props} vertical gap={16} style={{ position: 'relative' }}>
			{isFetching && <OverlayLoader />}

			<Typography.Title level={5} style={{ margin: 0 }}>
				{t('Отчеты')}
			</Typography.Title>

			<div className={styles.topbar}>
				<ReportsFilters />

				<Flex gap={12}>
					<Button
						size="small"
						icon={<ExportIcon />}
						onClick={() =>
							exportReport({
								params: searchParams.toString(),
								type: reportType,
								groupBy: reportGroubBy,
							})
						}>
						{isMd ? '' : t('Экспортировать')}
					</Button>

					<Popover
						content={<ReportsSort columns={columns} setColumns={setColumns} />}
						trigger="click"
						placement="bottomRight">
						<Button size="small" icon={<TableIcon />}>
							{t('Настроить таблицу')}
						</Button>
					</Popover>
				</Flex>
			</div>

			{!hasData && !isFetching && <EmptyState title={t('Пока нет отчетов')} />}

			{hasData && (
				<>
					<ConfigProvider
						theme={{
							components: {
								Table: {
									marginXXS: 16,
								},
							},
						}}>
						<Table<IReportDataType>
							{...tableProps}
							dataSource={results.map<IReportDataType>((report, i) =>
								getReport(report as IActionReport, i, reportGroubBy, reportType),
							)}
							onChange={getTableSorter<IReportDataType>(searchParams, setSearchParams)}
						/>
					</ConfigProvider>

					<Pagination count={data?.count || 1} />
				</>
			)}
		</Flex>
	);
};
